def parse_multipart_parts(raw_body: str, boundary: str) -> list:
    """Parse multipart form fields without limiting total parts count.
    VULNERABLE: Attacker sending 100,000 tiny parts causes resource exhaustion.
    """
    delimiter = f"--{boundary}"
    raw_parts = raw_body.split(delimiter)
    parts = []
    for chunk in raw_parts:
        c = chunk.strip()
        if c and c != "--":
            parts.append(c)
    return parts

